        self.buffer.seek(0)
        self._traverse_codepoints(0, pos)
        self._tell = pos
    # Seek to new position relative to current position
    elif mode == os.SEEK_CUR:
        start_pos = self.tell()
        new_pos = start_pos + pos
        if new_pos < 0:
            raise ValueError(
                f"Negative seek position {new_pos}"
            )
        self._traverse_codepoints(start_pos, pos)
        self._tell = new_pos
    elif mode == os.SEEK_END:
        self.buffer.seek(0)
        dest_position = self.len - pos
        if dest_position < 0:
            raise ValueError(
                f"Negative seek position {dest_position}"
            )
        self._traverse_codepoints(0, dest_position)
        self._tell = dest_position
    else:
        raise ValueError(
            f"Invalid whence ({mode}, should be 0, 1, or 2)"
        )
    return self.tell()

